import {newGame,reduceGame,SCENES,ITEMS,ending,GAME_VERSION} from './play-state.mjs';
import {createVoices} from './voices.mjs'; import {fx,toggleSound} from './audio.mjs';
const $=id=>document.getElementById(id), saveKey='life-book-4.0'; let g=newGame(),active=false,modalOpen=false,voices=createVoices(),refs=[],refIndex=0;
try{const s=JSON.parse(localStorage.getItem(saveKey));if(s?.version===GAME_VERSION)g=s;}catch{}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem(saveKey,JSON.stringify(g));}
function btn(label,a,cls='',attrs=''){return `<button type="button" class="${cls}" data-a="${a}" ${attrs}>${label}</button>`}
function render(){document.body.dataset.scene=active?g.scene:'cover';$('dock').hidden=!active;$('chapterHud').textContent=active?`大学篇 / ${SCENES[g.scene].year} · ${SCENES[g.scene].title}`:'大学篇 / 一页一页走进去';$('bagCount').textContent=`记忆 ${g.memories.length}`;$('play').innerHTML=active?(g.scene===SCENES.length-1?finale():scene()):cover();}
function cover(){return `<section class="start-screen"><div class="cover-meta">人生之书 · 大学篇</div><div class="cover-title"><span>如果现在的你，重新走进大学。</span><h1>这一页，<br><b>由你落笔。</b></h1><p>你会怎么度过这四年？</p>${btn('打开大学篇 ↵','start','primary')}</div><div class="cover-bottom"><span>有限时间 · 每次取舍 · 一章人生</span><span>知乎真实经历 · 可借用的方法</span></div></section>`}
function scene(){const s=SCENES[g.scene];const objects=(s.objects||[]).map(([id,t,sub])=>btn(`<b>${ITEMS[id]?.icon||'•'}</b><strong>${t}</strong><small>${sub}</small><i>${g.inspected.includes(id)?'已查看 ✓':'点开'}</i>`,'inspect','scene-object '+(g.inspected.includes(id)?'seen':''),`data-id="${id}"`)).join('');const choices=s.choices.map(([id,label,gain,cost])=>btn(`<span>→</span><strong>${label}</strong><small>得到：${gain}<br>付出：${cost}</small>`,'choose','choice',`data-id="${id}"`)).join('');return `<section class="scene-enter"><div class="scene-head"><span class="eyebrow">${s.kicker}</span><h1>${s.title}</h1><p>${s.intro}</p></div><div class="scene-layout"><div class="scene-art"><div class="art-caption">${s.year}</div><div class="objects">${objects}</div></div><div class="scene-actions"><span class="eyebrow">这一页，你只能做一两件事</span>${choices}</div></div><div class="page-footer"><span>第 ${g.scene+1} / ${SCENES.length} 页</span>${g.scene?btn('← 回到上一页','back','quiet'):''}</div></section>`}
function modal(title,html){modalOpen=true;$('dialogTitle').textContent=title;$('dialogBody').innerHTML=html;$('dialog').showModal();}
function close(){modalOpen=false;$('dialog').close();}
function inspect(id){const it=ITEMS[id];modal(it.title,`<div class="object-modal"><b>${it.icon}</b><h3>${it.title}</h3><p>${it.sub}</p><p class="modal-line">你把这件东西记住了。它可能会在很久以后回来。</p>${btn('收进这一页','close','primary')}</div>`);if(!g.inspected.includes(id)){g.inspected.push(id);save();render();}fx(id==='voice'?'message':'paper');}
function choose(id){const ok=(()=>{try{g=reduceGame(g,{type:'choose',id});save();return true}catch(e){alert(e.message);return false}})();if(ok){fx('page');render();if(g.lastSource)showVoices();}}
function showVoices(){const d=voices.current(g);refs=d.view.references||[];refIndex=0;drawVoices(d.reason);voices.search(g).then(x=>{if(x?.view?.references?.length&&modalOpen){refs=x.view.references;drawVoices(x.reason)}}).catch(()=>{});}
function drawVoices(status){const r=refs[refIndex];if(!r)return modal('页边来信','暂时没有可用的经历。');modal('知乎 · 页边来信',`<div class="voices-panel"><small>${esc(status||'真实经历摘要')} · ${refIndex+1}/${refs.length}</small><div class="voice-source"><span class="zhi">知</span><span>${esc(r.author)}<em>${esc(r.type)}</em></span></div><h3>${esc(r.short_summary||r.summary)}</h3><div class="voice-action"><small>可以借用的方法</small><p>${esc(r.lens?.label||r.action||'先把问题拆成一个小行动。')}</p></div><details><summary>查看出处</summary><h4>${esc(r.title)}</h4><p>${esc(r.summary)}</p><a href="${esc(r.url)}" target="_blank">去知乎读原文 ↗</a><small>角色与结果为游戏创作，摘要不是作者完整人生。</small></details><div class="voice-controls">${btn('←','prev','quiet')}${btn('借用这条经验，继续 →','adopt','primary')}${btn('→','next','quiet')}</div></div>`)}
function adopt(){const r=refs[refIndex];try{g=reduceGame(g,{type:'source',source:r});save();close();render();}catch(e){alert(e.message)}}
function finale(){return `<section class="ending-scene"><h1>${ending(g).title}</h1><p>${ending(g).text}</p><div class="memory-shelf">${g.memories.map(id=>`<div><b>${ITEMS[id]?.icon}</b><strong>${ITEMS[id]?.title}</strong></div>`).join('')}</div><label>如果现在的我重新走进大学，我会……</label><textarea id="todayAction" rows="3">${esc(g.today)}</textarea>${btn('把这一页带回今天 ↓','today','primary')}</section>`}
function handle(a,d){if(a==='start'){active=true;g.started=true;save();render();return}if(a==='close'){close();return}if(a==='inspect'){inspect(d.id);return}if(a==='choose'){choose(d.id);return}if(a==='back'){try{g=reduceGame(g,{type:'back'});save();render()}catch(e){alert(e.message)}return}if(a==='voices'){showVoices();return}if(a==='bag'){modal('你留下的东西',g.memories.map(id=>`<p>${ITEMS[id]?.icon} ${ITEMS[id]?.title}</p>`).join('')||'还没有物件。');return}if(a==='prev'){refIndex=(refIndex-1+refs.length)%refs.length;drawVoices('知乎页边来信');return}if(a==='next'){refIndex=(refIndex+1)%refs.length;drawVoices('知乎页边来信');return}if(a==='adopt'){adopt();return}if(a==='today'){g.today=$('todayAction').value;save();modal('这一页已经写下',`<p>${esc(g.today)}</p>${btn('重新开始','restart','primary')}`);return}if(a==='restart'){g=newGame();active=false;close();render();return}}
$('play').addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b&&!b.disabled){fx('click');handle(b.dataset.a,b.dataset)}});$('dialogBody').addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b)handle(b.dataset.a,b.dataset)});$('closeDialog').onclick=close;$('voiceBtn').onclick=showVoices;$('bagBtn').onclick=()=>handle('bag');$('soundBtn').onclick=async()=>{const on=await toggleSound();$('soundBtn').innerHTML=`♫ <span>声音${on?'开':'关'}</span>`};render();
